interface Config {
  readonly retries: number;
  endpoint: string;
}

function createClient(cfg: Config) {
  return {
    async call(path: string) {
      for (let i = 0; i < cfg.retries; i++) {
        const res = await fetch(cfg.endpoint + path);
        if (res.ok) return res.json();
      }
      throw new Error('exhausted retries');
    },
  };
}

function isRecord(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null;
}

function getString(obj: Record<string, unknown>, key: string): string | undefined {
  const val = obj[key];
  return typeof val === 'string' ? val : undefined;
}

// C# pattern for Control flow analysis and unreachable code (never)
public sealed record Config(int Retries, string Endpoint);

public async Task<JsonDocument> CallAsync(Config cfg, string path) {
    for (var i = 0; i < cfg.Retries; i++) {
        var res = await _http.GetAsync(cfg.Endpoint + path);
        if (res.IsSuccessStatusCode) return await JsonDocument.ParseAsync(await res.Content.ReadAsStreamAsync());
    }
    throw new InvalidOperationException("exhausted retries");
}

function diagnose(error: unknown): string {
  if (error instanceof Error) return error.message;
  if (typeof error === 'string') return error;
  return 'unknown failure';
}
